subsection.code:
You received three independent web search results for
the query: {query}

Source A (Grok/xAI): {response_grok}
Source B (GPT/OpenAI): {response_openai}
Source C (Gemini/Google): {response_gemini}

Synthesize a single answer:
- Facts confirmed by 2+ sources: state as confirmed
- Facts from only one source: state with attribution
- Contradictions between sources: state the contradiction
- Source URLs: deduplicate and list
- If any source found nothing: note the gap

Be concise. The caller is an agent, not a human.

defmodule Froth.Search do
  @moduledoc """
  Triangulated web search via multi-provider fan-out.

  Sends the same query to Grok, OpenAI, and Gemini simultaneously,
  then collates results via a fourth LLM call.
  """

  @providers [
    {Froth.Search.Grok,   "grok-4-1-fast-reasoning"},
    {Froth.Search.OpenAI, "gpt-5.4"},
    {Froth.Search.Gemini, "gemini-3.1-pro"}
  ]

  def search(query, opts \\ []) do
    timeout = opts[:timeout] || 15_000

    results =
      @providers
      |> Task.async_stream(
        fn {mod, model} -> mod.search(query, model: model) end,
        timeout: timeout,
        on_timeout: :kill_task
      )
      |> Enum.map(fn
        {:ok, result} -> result
        {:exit, :timeout} -> {:timeout, "provider timed out"}
      end)

    collate(query, results, opts)
  end

  defp collate(query, results, opts) do
    # Fourth call: Anthropic collates
    Froth.Anthropic.chat(collation_prompt(query, results),
      model: opts[:collation_model] || "claude-sonnet-4-20250514"
    )
  end
end

defmodule Froth.Search.Grok do def search(query, opts) do Froth.Analyzer.API.grok_search( "Search the web for: #{query}

Return factual findings...", model: opts[:model] ) end end
defmodule Froth.Search.OpenAI do def search(query, opts) do # OpenAI Responses API with web_search_preview Froth.OpenAI.responses( "Search the web for: #{query}

Return factual findings...", model: opts[:model], tools: [%{type: "web_search_preview"}] ) end end
defmodule Froth.Search.Gemini do def search(query, opts) do # Gemini with google_search_retrieval grounding Froth.Gemini.generate( "Search the web for: #{query}

Return factual findings...", model: opts[:model], tools: [%{google_search_retrieval: %{ dynamic_retrieval_config: %{ mode: "MODE_DYNAMIC", dynamic_threshold: 0.3 } }}] ) end end

{
  "name": "web_search",
  "description": "Search the web via three independent providers simultaneously. Returns triangulated results with source attribution and confidence markers.",
  "parameters": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "description": "The search query. Be specific."
      }
    },
    "required": ["query"]
  }
}

Froth.Search.query("Iranian anti-ship missile capabilities March 2026",
  providers: [:grok, :openai, :gemini],  # default: all three
  collate: true,                          # default: true
  timeout: 30_000                         # per-provider timeout, ms
)

# Returns:
{:ok, %Froth.Search.Result{
  query: "...",
  sources: %{
    grok: %{text: "...", citations: [...], status: :ok},
    openai: %{text: "...", citations: [...], status: :ok},
    gemini: %{text: "...", citations: [...], status: :timeout}
  },
  collated: "...",          # nil if collate: false
  agreement: 0.85,          # fraction of claims confirmed by 2+ sources
  single_source_claims: [...] # claims found in only one provider
}}
